SELECT p.park_code, -- 计算该园区有多少个指标是有数据的 (非零) ( IF(IFNULL(t1.cnt, 0) > 0, 1, 0) + IF(IFNULL(t2.cnt, 0) > 0, 1, 0) + IF(IFNULL(t3.cnt, 0) > 0, 1, 0) + IF(IFNULL(t4.cnt, 0) > 0, 1, 0) + IF(IFNULL(t5.cnt, 0) > 0, 1, 0) + IF(IFNULL(t6.cnt, 0) > 0, 1, 0) + IF(IFNULL(t7.cnt, 0) > 0, 1, 0) + IF(IFNULL(t8.cnt, 0) > 0, 1, 0) + IF(IFNULL(t9.cnt, 0) > 0, 1, 0) + IF(IFNULL(t10.cnt, 0) > 0, 1, 0) + IF(IFNULL(t11.cnt, 0) > 0, 1, 0) + IF(IFNULL(t12.cnt, 0) > 0, 1, 0) ) as nonZeroCount FROM ( -- 1. 构造传入的 parkCode 列表作为主表，确保即使某园区全为0也能被统计到
SELECT #{code} as park_code
) p -- 2. 左连接 12 张表，分别统计每个 park_code 的数量 LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjyaxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t1 ON p.park_code = t1.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjyljhxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t2 ON p.park_code = t2.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjylssgcjl WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t3 ON p.park_code = t3.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjwzjcxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t4 ON p.park_code = t4.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjjydwxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t5 ON p.park_code = t5.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjzjxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t6 ON p.park_code = t6.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjbncsxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t7 ON p.park_code = t7.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.ylzyxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t8 ON p.park_code = t8.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.jjjl WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t9 ON p.park_code = t9.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.xbjl WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t10 ON p.park_code = t10.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.jyczgcjl WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t11 ON p.park_code = t11.park_code LEFT JOIN (SELECT park_code, COUNT(*) as cnt FROM shipingtaishujuzhongxin.yjczfajl WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code) t12 ON p.park_code = t12.park_code
